import numpy as np
def equation(t, P, params):
    base = params[0] + params[1]*P + params[2]*P**2 + params[3]*P*np.log(P) + params[4]*np.exp(-P) + params[5]*P*np.exp(-P)
    tt = params[6]*t + params[7]*t**2
    return base + tt*(params[8]*P + params[9]*P*np.log(P))
